/// tsgo `commandLineOptionDeprecated`: the enum keys help leaves out.
pub(crate) fn deprecated_keys(option: &str) -> &'static [&'static str] {
    match option {
        "module" => &["none", "amd", "system", "umd"],
        "moduleResolution" => &["node", "classic", "node10"],
        "target" => &["es5"],
        _ => &[],
    }
}
